const input = $input.item.json;

// Validate required fields
const source = input.source;
const sourceId = input.source_id;
const content = input.content;
const title = input.title || '';
const sessionId = input.session_id || null;

if (!source || !['conversation', 'document'].includes(source)) {
  return [{ json: { error: 'Invalid source type. Must be "conversation" or "document".', success: false } }];
}

if (!sourceId) {
  return [{ json: { error: 'source_id is required.', success: false } }];
}

if (!content || content.trim().length === 0) {
  return [{ json: { error: 'content is required and must not be empty.', success: false } }];
}

// Chunking parameters
const CHUNK_SIZE = 1500;
const CHUNK_OVERLAP = 200;

// Split content into overlapping chunks on paragraph boundaries
const paragraphs = content.split(/\n\n+/);
const chunks = [];
let currentChunk = '';
let chunkIndex = 0;

for (const para of paragraphs) {
  if (currentChunk.length + para.length + 2 > CHUNK_SIZE && currentChunk.length > 0) {
    chunks.push({
      text: currentChunk.trim(),
      chunk_index: chunkIndex
    });
    chunkIndex++;
    // Overlap: keep the tail of the current chunk
    if (currentChunk.length > CHUNK_OVERLAP) {
      currentChunk = currentChunk.substring(currentChunk.length - CHUNK_OVERLAP) + '\n\n' + para;
    } else {
      currentChunk = currentChunk + '\n\n' + para;
    }
  } else {
    currentChunk = currentChunk ? currentChunk + '\n\n' + para : para;
  }
}

// Don't forget the last chunk
if (currentChunk.trim().length > 0) {
  chunks.push({
    text: currentChunk.trim(),
    chunk_index: chunkIndex
  });
}

// If content was too small for paragraph splitting, use it as a single chunk
if (chunks.length === 0) {
  chunks.push({ text: content.trim(), chunk_index: 0 });
}

// Generate deterministic UUIDs for each chunk
function deterministicUUID(str) {
  let h1 = 0xdeadbeef;
  let h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507);
  h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507);
  h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  const hex1 = (h1 >>> 0).toString(16).padStart(8, '0');
  const hex2 = (h2 >>> 0).toString(16).padStart(8, '0');
  return hex1.substring(0, 8) + '-' + hex1.substring(4, 8) + '-4' + hex2.substring(0, 3) + '-8' + hex2.substring(3, 6) + '-' + hex2.padStart(12, '0').substring(0, 12);
}

return chunks.map(chunk => ({
  json: {
    source,
    source_id: sourceId,
    title,
    session_id: sessionId,
    chunk_text: chunk.text,
    chunk_index: chunk.chunk_index,
    total_chunks: chunks.length,
    point_id: deterministicUUID(sourceId + ':' + chunk.chunk_index),
    content_preview: chunk.text.substring(0, 200)
  }
}));

const embedResult = $input.item.json;
const chunkData = $('Validate And Chunk').item.json;

// Check for error from validation
if (chunkData.error) {
  return [{ json: { skip: true, error: chunkData.error, success: false } }];
}

// Extract embedding
const embedding = embedResult.data && embedResult.data[0] && embedResult.data[0].embedding
  ? embedResult.data[0].embedding
  : null;

if (!embedding) {
  return [{ json: { skip: true, error: 'No embedding returned', source_id: chunkData.source_id, chunk_index: chunkData.chunk_index } }];
}

return [{
  json: {
    skip: false,
    qdrant_payload: {
      points: [{
        id: chunkData.point_id,
        vector: embedding,
        payload: {
          source: chunkData.source,
          source_id: chunkData.source_id,
          session_id: chunkData.session_id,
          title: chunkData.title,
          content_preview: chunkData.content_preview,
          chunk_index: chunkData.chunk_index,
          total_chunks: chunkData.total_chunks,
          timestamp: new Date().toISOString()
        }
      }]
    },
    source: chunkData.source,
    source_id: chunkData.source_id,
    chunk_index: chunkData.chunk_index,
    total_chunks: chunkData.total_chunks,
    session_id: chunkData.session_id
  }
}];

const allChunks = $('Validate And Chunk').all();
const storeResults = $('Store in Qdrant').all();

let storedCount = 0;
let source = '';
let sourceId = '';
let sessionId = null;

for (let i = 0; i < storeResults.length; i++) {
  const result = storeResults[i].json;
  if (result && result.status === 'ok') {
    storedCount++;
  }
}

if (allChunks.length > 0) {
  source = allChunks[0].json.source || '';
  sourceId = allChunks[0].json.source_id || '';
  sessionId = allChunks[0].json.session_id || null;
}

return [{
  json: {
    success: storedCount > 0,
    source,
    source_id: sourceId,
    chunks_stored: storedCount,
    total_chunks: allChunks.length,
    session_id: sessionId
  }
}];
